function shiftForTask(t){const time=taskTime(t).value;if(!/^\d{2}:\d{2}$/.test(time))return null;const h=Number(time.slice(0,2));return h<12?'Manhã':h<18?'Tarde':'Noite'}
function roleForTask(t){if(t.front==='Stories')return 2;if(t.front!=='Feed')return null;if(/CARROSSEL/i.test(t.title))return 5;if(/CORTE/i.test(t.title))return 4;return 3}
function scaleKey(row,role){return `${row.id??(row.day+'-'+row.shift)}-${role}`}
function scaleMembers(row,role){return state.scaleOwners[scaleKey(row,role)]??row.members[role].join(', ')}
function rosterOwner(t){const role=roleForTask(t);if(role===null)return 'A definir';const shift=shiftForTask(t),rows=state.roster.filter(r=>r.day===t.day&&(!shift||r.shift===shift));if(!rows.length)return 'Responsáveis a definir';if(rows.length===1)return scaleMembers(rows[0],role)||'A definir';return rows.map(r=>`${r.shift}: ${scaleMembers(r,role)||'não informado'}`).join(' · ')+' · Turno da demanda a confirmar'}
function taskOwner(t){return t.owner||rosterOwner(t)}
function relatedToScale(row,role){return state.tasks.filter(t=>t.day===row.day&&((role===2&&t.front==='Stories')||(role===3&&t.front==='Feed'&&roleForTask(t)===3)||(role===4&&t.front==='Feed'&&roleForTask(t)===4)||(role===5&&t.front==='Feed'&&roleForTask(t)===5)||(role===0&&t.front==='Stories'&&t.checks.some(c=>/foto|fotos/i.test(c.label))))&&(!shiftForTask(t)||shiftForTask(t)===row.shift))}
function scaleCard(row,role){const key=scaleKey(row,role),steps=SCALE_PROCESSES[role],related=relatedToScale(row,role),done=steps.filter((_,i)=>state.scaleChecks[key]?.[i]).length;return `<article class="scale-card"><div class="task-tags"><span class="tag">${esc(row.shift)}</span><span class="tag">ESCALA / FUNÇÃO</span></div><h3>${SCALE_ROLES[role]}</h3><div class="daily-owner"><span>RESPONSÁVEIS DESTA ESCALA</span><strong data-scale-owner="${key}">${esc(scaleMembers(row,role)||'A definir')}</strong></div><a class="area-process-link" href="processos.html#area-${role}" target="_blank" rel="noopener">Confira o processo de ${SCALE_ROLES[role]} ↗</a><label class="daily-check scale-finished"><input type="checkbox" data-scale-done="${key}" ${state.scaleDone[key]?'checked':''}><span>Entregas e backups desta escala concluídos no Drive e conferidos com a equipe</span><small>${state.scaleDone[key]?'Feito ✓':'A fazer'}</small></label><div class="scale-linked"><h4>Demandas relacionadas · ${related.length}</h4>${role===0?'<p class="note">Registre os momentos do turno e confira os itens de fotografia abaixo.</p>':''}${role===1?'<p class="note">Receba e trate os arquivos da equipe de fotografia deste turno.</p>':''}${related.map(t=>{const list=role===0?t.checks.filter(c=>/foto|fotos/i.test(c.label)):t.checks;return `<div class="linked-demand"><strong>${esc(t.title)}</strong>${povGuidance(t)}<small>${esc(taskTime(t).value)}${!shiftForTask(t)?' · Demanda do dia: distribuição entre turnos a confirmar':' · '+row.shift}</small>${list.map(c=>`<label class="daily-check"><input type="checkbox" data-demand="${esc(t.id)}" data-demand-check="${esc(c.id)}" ${c.done?'checked':''}><span>${esc(c.label)}</span></label>`).join('')}<a href="#daily-${esc(t.id)}">Ver na programação ↗</a></div>`}).join('')||'<p class="note">Confira a programação do turno e alinhe as entregas com sua equipe.</p>'}</div></article>`}
function renderRosterTables(){return ['1','2','3','4','5'].filter(d=>state.roster.some(r=>r.day===d)||editing).map(day=>{const rows=state.roster.filter(r=>r.day===day),title=['','Sexta-feira','Sábado','Domingo','Segunda-feira','Terça-feira'][day],friday=false;return `<article class="roster-day" id="escala-dia-${day}"><div class="roster-title"><span>DIA ${day}</span><h3>${title}</h3><a href="#dia-${day}">Programação deste dia ↗</a></div><div class="roster-table-wrap"><table class="roster-table"><caption>Escala de ${title}</caption><thead><tr>${friday?'':'<th scope="col">Turno</th>'}${SCALE_ROLES.map((role,i)=>`<th scope="col">${esc(role)}${i===2?'<small>Inclui edição, POVs e entrevistas dos stories</small>':i===3?'<small>Inclui POVs e entrevistas do feed</small>':''}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${friday?'':`<th scope="row" class="roster-shift">${esc(row.shift)}${editing?`<button class="scale-row-edit" data-edit-scale="${esc(row.id)}">Editar turno</button>`:''}</th>`}${SCALE_ROLES.map((role,i)=>`<td data-label="${esc(role)}"><strong data-scale-owner="${scaleKey(row,i)}">${esc(scaleMembers(row,i)||'A definir')}</strong></td>`).join('')}</tr>`).join('')}</tbody></table></div></article>`}).join('')}
function renderScales(){const day=document.querySelector('#scaleDay')?.value??'',shift=document.querySelector('#scaleShift')?.value??'',role=document.querySelector('#scaleRole')?.value??'';return ['1','2','3','4','5'].filter(d=>(!day||day===d)&&state.roster.some(r=>r.day===d)).map(d=>{const rows=state.roster.filter(r=>r.day===d&&(!shift||r.shift===shift));return `<div class="scale-day"><h3>${['','Sexta-feira','Sábado','Domingo','Segunda-feira','Terça-feira'][d]}</h3>${rows.map(row=>`<div class="scale-turn"><div class="scale-turn-title">${esc(row.shift)} · Dia ${d}</div><div class="scale-grid">${SCALE_ROLES.map((r,i)=>role===''||role===String(i)?scaleCard(row,i):'').join('')}</div></div>`).join('')||'<p>Não há turno informado para este filtro.</p>'}</div>`}).join('')}
function refreshScales(){const el=document.querySelector('#scaleBoards');if(el)el.innerHTML=renderScales();const overview=document.querySelector('#rosterTables');if(overview)overview.innerHTML=renderRosterTables();document.querySelectorAll('[data-scale-owner]').forEach(el=>el.contentEditable=editing?'true':'false')}
function taskTime(t){
 const custom=state.events.find(e=>e.id===t.id);
 if(custom?.time&&custom.time!=='A confirmar')return {value:custom.time,label:'Horário do momento'};
 if(t.time&&t.time!=='A confirmar')return {value:t.time,label:t.front==='Feed'?'Horário de captação':'Horário do momento'};
 if(t.front==='Feed'){
 const related=state.tasks.filter(x=>x.front==='Stories'&&x.day===t.day&&x.time&&x.time!=='A confirmar');
 const aula=t.title.match(/AULA\s*(\d+)/i),pov=t.title.match(/POV\s*(\d+)/i);
 let match=aula?related.find(x=>new RegExp('AULA\\s*0?'+Number(aula[1])+'(?:\\D|$)','i').test(x.title)):null;
 if(!match&&/LOUVOR/.test(t.title)&&!t.title.includes('CARROSSEL'))match=related.find(x=>/LOUVOR/i.test(x.title));
 if(!match&&t.day==='1'&&/PALAVRA/.test(t.title))match=related.find(x=>/PALAVRA/i.test(x.title));
 if(!match&&t.day==='1'&&pov?.[1]==='1')match=related.find(x=>/Credenciamento/i.test(x.title));
 if(match)return {value:state.events.find(e=>e.id===match.id)?.time||match.time,label:'Captação no momento relacionado'};
 return {value:'A confirmar',label:'Horário de captação / publicação'};
 }
 return {value:'A confirmar',label:'Horário a confirmar'};
}
function povGuidance(t){return /^POV\s*\d+\s*\|\s*[.]*$/i.test(t.title.trim())?'<div class="pov-guidance"><strong>POV com tema livre</strong><p>Voluntário escalado: você tem liberdade para ser guiado pelo Espírito na escolha do tema e do olhar sobre o momento. Consulte também nosso grupo de inspirações para o feed e alinhe a produção ao propósito da CALL 16:15.</p></div>':''}
function dailyCard(t){const done=t.checks.filter(c=>c.done).length,time=taskTime(t);return `<article class="daily-card ${t.front==='Stories'?'story-card':'feed-card'}" id="daily-${esc(t.id)}"><div class="daily-meta"><span class="front-badge">${esc(t.front)}</span><span class="daily-time">${esc(time.value)}</span></div><small class="time-caption">${esc(time.label)}</small><h3>${esc(t.title)}</h3>${povGuidance(t)}<div class="daily-owner"><span>QUEM FAZ</span><strong>${esc(taskOwner(t))}</strong></div>${t.front==='Feed'?'<p class="publication-note">O horário de captação acompanha o momento, quando identificado. O prazo para publicar será definido pela coordenação.</p>':''}<div class="daily-progress"><progress max="${t.checks.length||1}" value="${done}"></progress><span>${done} de ${t.checks.length} feitos</span></div><div class="visible-checks">${t.checks.map(c=>`<label class="daily-check"><input type="checkbox" data-demand="${esc(t.id)}" data-demand-check="${esc(c.id)}"><span>${esc(c.label)}</span><small>${c.done?'Feito ✓':'A fazer'}</small></label>`.replace('data-demand-check="'+esc(c.id)+'"','data-demand-check="'+esc(c.id)+'" '+(c.done?'checked':''))).join('')||'<p>Sem itens detalhados. Use Editar demanda para adicionar.</p>'}</div>${t.brief?`<details class="day-detail"><summary>Orientações da demanda</summary><p>${esc(t.brief)}</p></details>`:''}<div class="daily-actions"><label>Etapa da demanda<select data-status="${esc(t.id)}">${['Planejado','Em produção','Em revisão','Concluído'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></label><button data-edit-task="${esc(t.id)}">Editar demanda / responsável</button></div></article>`}
function renderDays(){return ['Sexta · Culto de Avivamento I','Sábado · Ensino & Avivamento','Domingo · Ensino & Comunhão','Segunda · Prático & Lava-pés','Terça · Evangelismo na praça'].map((title,i)=>{const d=String(i+1),tasks=state.tasks.filter(t=>t.day===d),checks=tasks.flatMap(t=>t.checks),done=checks.filter(c=>c.done).length;return `<section class="conference-day" id="dia-${d}"><div class="day-heading"><div><div class="eyebrow">DIA ${d} / COMUNICAÇÃO</div><h2>${title}</h2></div><div class="day-total"><strong>${done}/${checks.length}</strong><span>atividades feitas</span></div></div><div class="day-local-nav"><a class="stories-link" href="#dia-${d}-stories">✳ Ver Stories</a><a class="feed-link" href="#dia-${d}-feed">▤ Ver Feed</a><a href="#programacao">Escolher outro dia ↑</a></div>${d==='1'?'<div class="event"><div class="time">20:35</div><div><h3>Transição e Boas-Vindas</h3><p>Emanuelle Monteiro</p></div></div>':''}${['Stories','Feed'].map(front=>{const items=tasks.filter(t=>t.front===front);return `<div class="daily-front ${front==='Stories'?'stories-front':'feed-front'}" id="dia-${d}-${front.toLowerCase()}"><div class="front-heading"><span class="front-icon">${front==='Stories'?'✳':'▤'}</span><div><h3>${front}</h3><p>${front==='Stories'?'Cobertura do que acontece ao vivo: bastidores, falas e momentos.':'Conteúdos para o perfil: reels, cortes, carrosséis, entrevistas e pós-CALL.'}</p></div><strong>${items.length} demandas</strong></div><div class="daily-grid">${items.map(dailyCard).join('')||'<p>Nenhuma demanda nesta frente.</p>'}</div></div>`}).join('')}<a class="back-days" href="#programacao">↑ Voltar aos dias</a></section>`}).join('')}
function refreshDaily(){const el=document.querySelector('#dailyProgram');if(el)el.innerHTML=renderDays()}
function refreshTaskViews(){const opened=[...document.querySelectorAll('.demand-details[open]')].map(d=>d.closest('.task').id);const details=[...document.querySelectorAll('.day-detail[open]')].map(d=>d.closest('.daily-card').id);renderBoard();refreshDaily();refreshScales();opened.forEach(id=>{const el=document.getElementById(id)?.querySelector('details');if(el)el.open=true});details.forEach(id=>{const el=document.getElementById(id)?.querySelector('details');if(el)el.open=true})}
function applyEdit(){document.body.classList.toggle('editing',editing);document.querySelector('#edit').textContent=editing?'Concluir edição ✓':'Editar planejamento ↗';document.querySelectorAll('[data-text],[data-event],[data-scale-owner],[data-copy],[data-schedule]').forEach(el=>{el.contentEditable=editing?'true':'false';el.spellcheck=editing})}
function renderBoard(){
 const q=document.querySelector('#search')?.value.toLowerCase()??'',f=document.querySelector('#filter')?.value??'',d=document.querySelector('#dayFilter')?.value??'',front=document.querySelector('#frontFilter')?.value??'';
 const visible=state.tasks.filter(t=>(!f||t.sector===f)&&(!d||t.day===d)&&(!front||t.front===front)&&`${t.title} ${t.owner} ${t.brief} ${t.checks.map(c=>c.label).join(' ')}`.toLowerCase().includes(q));
 const totalChecks=visible.reduce((n,t)=>n+t.checks.length,0),doneChecks=visible.reduce((n,t)=>n+t.checks.filter(c=>c.done).length,0);
 document.querySelector('#demandStats').innerHTML=`<div><strong>${visible.length}</strong><span>demandas no filtro</span></div><div><strong>${doneChecks}/${totalChecks}</strong><span>checks concluídos</span></div><div><strong>${visible.filter(t=>t.status==='Concluído').length}</strong><span>demandas concluídas</span></div><div><strong>${visible.filter(t=>!t.owner.trim()).length}</strong><span>aguardando responsável</span></div>`;
 document.querySelector('#board').innerHTML=['Planejado','Em produção','Em revisão','Concluído'].map((status,i)=>{const tasks=visible.filter(t=>t.status===status);return `<div class="column"><div class="colhead"><span>${String(i+1).padStart(2,'0')} / ${status}</span><span>${tasks.length}</span></div>${tasks.map(t=>`<article class="task" id="demand-${esc(t.id)}"><div class="task-tags"><span class="tag">${t.day==='0'?'Regras':'Dia '+esc(t.day)} · ${esc(t.front)}</span><span class="tag">${esc(t.sector)}</span></div><h3>${esc(t.title)}</h3>${povGuidance(t)}<p>Responsável da comunicação: <strong>${esc(taskOwner(t))}</strong>${t.time&&t.time!=='A confirmar'?'<br>Horário: '+esc(t.time):''}${t.due?'<br>Prazo: '+esc(t.due.replace('T',' · ')):''}</p><div class="task-progress"><progress max="${t.checks.length||1}" value="${t.checks.filter(c=>c.done).length}"></progress><span>${t.checks.filter(c=>c.done).length}/${t.checks.length}</span></div><details class="demand-details"><summary>Checklist e detalhes ↓</summary>${t.checks.map(c=>`<label class="demand-check"><input type="checkbox" data-demand="${esc(t.id)}" data-demand-check="${esc(c.id)}" ${c.done?'checked':''}><span>${esc(c.label)}</span></label>`).join('')}${t.brief?`<div class="original-detail"><strong>Orientações da demanda</strong><p>${esc(t.brief)}</p></div>`:''}</details><select data-status="${esc(t.id)}" aria-label="Status de ${esc(t.title)}">${['Planejado','Em produção','Em revisão','Concluído'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><button data-edit-task="${esc(t.id)}">Editar / atribuir</button> <button data-remove-task="${esc(t.id)}">Remover</button></article>`).join('')||'<div class="empty">Sem entregas nesta etapa.</div>'}</div>`}).join('');
}
function bind(){['#scaleDay','#scaleShift','#scaleRole'].forEach(id=>document.querySelector(id).onchange=refreshScales);document.querySelector('#search').oninput=renderBoard;document.querySelector('#filter').onchange=renderBoard;document.querySelector('#dayFilter').onchange=renderBoard;document.querySelector('#frontFilter').onchange=renderBoard;document.querySelector('#addTask').onclick=()=>openTask();document.querySelector('#export').onclick=()=>{save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='call1615-planejamento.json';a.click();URL.revokeObjectURL(url);toast('Planejamento exportado.')};document.querySelector('#import').onclick=()=>document.querySelector('#importFile').click();document.querySelector('#importFile').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!data||typeof data.text!=='object'||Array.isArray(data.text)||typeof data.checks!=='object'||!Array.isArray(data.events)||!Array.isArray(data.tasks)||data.events.some(x=>!x||!['1','2','3','4','5'].includes(x.day)||typeof x.id!=='string'||typeof x.title!=='string'||typeof x.time!=='string'||typeof x.brief!=='string')||data.tasks.some(x=>!x||typeof x.id!=='string'||typeof x.title!=='string'||!sectors.some(s=>s[0]===x.sector)||!['Planejado','Em produção','Em revisão','Concluído','Publicado'].includes(x.status)||!Array.isArray(x.checks??[])||(x.checks??[]).some(c=>!c||typeof c.id!=='string'||typeof c.label!=='string'||typeof c.done!=='boolean')))throw Error();if(data.roster&&(!Array.isArray(data.roster)||data.roster.some(r=>!r||typeof r.id!=='string'||!['1','2','3','4','5'].includes(r.day)||!['Manhã','Tarde','Noite'].includes(r.shift)||!Array.isArray(r.members)||r.members.length!==6||r.members.some(m=>!Array.isArray(m)))))throw Error();if(data.schedule&&(!Array.isArray(data.schedule)||data.schedule.some(r=>!r||typeof r.id!=='string'||!['1','2','3','4','5'].includes(r.day)||['block','time','title','minister'].some(k=>typeof r[k]!=='string'))))throw Error();if(confirm('Substituir o planejamento atual pelo arquivo importado? Exporte antes se quiser manter uma cópia.')){state=data;state.scaleDone??={};state.scaleChecks??={};state.scaleOwners??={};state.phraseChecks??={};state.roster??=structuredClone(SCALE_ROSTER).map(r=>({...r,id:r.day+'-'+r.shift}));state.copy??={};state.processText??={};state.schedule??=structuredClone(OFFICIAL_SCHEDULE);state.tasks.forEach(t=>{t.checks??=[];t.day??='0';t.front??='Feed';if(t.status==='Publicado')t.status='Concluído'});localStorage.setItem(KEY,JSON.stringify(state));render();toast('Planejamento importado.')}}catch{toast('Arquivo inválido. Use um JSON exportado por este site.')}};document.querySelector('#print').onclick=()=>window.print()}
document.querySelector('#edit').onclick=()=>{editing=!editing;render();toast(editing?'Clique nos textos para editar.':'Edição concluída.')};document.addEventListener('input',e=>{if(e.target.dataset.schedule&&editing){const row=state.schedule.find(r=>r.id===e.target.dataset.schedule);if(row){row[e.target.dataset.field]=e.target.innerText;save()}}if(e.target.dataset.copy&&editing){state.copy[e.target.dataset.copy]=e.target.innerText;save()}if(e.target.dataset.scaleOwner&&editing){state.scaleOwners[e.target.dataset.scaleOwner]=e.target.innerText;document.querySelectorAll('[data-scale-owner]').forEach(el=>{if(el!==e.target&&el.dataset.scaleOwner===e.target.dataset.scaleOwner)el.textContent=e.target.innerText});save();refreshDaily();renderBoard()}if(e.target.dataset.text&&editing){state.text[e.target.dataset.text]=e.target.innerText;save()}if(e.target.dataset.event&&editing){const item=state.events.find(x=>x.id===e.target.dataset.event);if(item){item[e.target.dataset.field]=e.target.innerText;save()}}});document.addEventListener('change',e=>{if(e.target.dataset.scaleDone){state.scaleDone[e.target.dataset.scaleDone]=e.target.checked;save();refreshScales()}if(e.target.dataset.scaleStep){state.scaleChecks[e.target.dataset.scale]??={};state.scaleChecks[e.target.dataset.scale][e.target.dataset.scaleStep]=e.target.checked;save();refreshScales()}if(e.target.dataset.phrase){state.phraseChecks[e.target.dataset.phrase]=e.target.checked;save()}if(e.target.dataset.demandCheck){const t=state.tasks.find(t=>t.id===e.target.dataset.demand);const c=t?.checks.find(c=>c.id===e.target.dataset.demandCheck);if(c){c.done=e.target.checked;save();refreshTaskViews();}}if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;save()}if(e.target.dataset.status){state.tasks.find(t=>t.id===e.target.dataset.status).status=e.target.value;save();refreshTaskViews()}});document.addEventListener('click',e=>{if(e.target.closest('[data-add-schedule]')&&editing)openSchedule();if(e.target.dataset.editSchedule&&editing)openSchedule(e.target.dataset.editSchedule);if(e.target.closest('[data-add-scale]')&&editing)openScale();if(e.target.dataset.editScale&&editing)openScale(e.target.dataset.editScale);if(e.target.dataset.removeTask&&confirm('Remover esta entrega?')){state.tasks=state.tasks.filter(t=>t.id!==e.target.dataset.removeTask);save();refreshTaskViews()}if(e.target.dataset.editTask)openTask(e.target.dataset.editTask);if(e.target.dataset.openDemand){const t=state.tasks.find(t=>t.id===e.target.dataset.openDemand);document.querySelector('#dayFilter').value=t.day;document.querySelector('#frontFilter').value=t.front;document.querySelector('#filter').value='';document.querySelector('#search').value='';renderBoard();const el=document.getElementById('demand-'+t.id);el.querySelector('details').open=true;el.scrollIntoView({behavior:'smooth',block:'center'})}});
let editTaskId=null;function openTask(id){editTaskId=id||null;const form=document.querySelector('#taskForm');form.reset();form.elements.sector.innerHTML=sectors.map(s=>`<option>${s[0]}</option>`).join('');if(id){const t=state.tasks.find(t=>t.id===id);['title','sector','owner','due','brief','day','front','time'].forEach(k=>form.elements[k].value=t[k]||'');form.elements.checkItems.value=t.checks.map(c=>c.label).join('\n')}document.querySelector('#taskDialog').showModal()}
document.querySelector('#cancel').onclick=()=>document.querySelector('#taskDialog').close();document.querySelector('#taskForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.title.trim())return;const old=state.tasks.find(t=>t.id===editTaskId);const labels=data.checkItems.split('\n').map(s=>s.trim()).filter(Boolean);delete data.checkItems;data.checks=labels.map((label,i)=>{const previous=old?.checks.find(c=>c.label===label);return previous||{id:crypto.randomUUID(),label,done:false}});if(old){Object.assign(old,data);const event=state.events.find(e=>e.id===old.id);if(event){event.time=old.time||'A confirmar';event.title=old.title;event.brief=old.brief}}else state.tasks.push({...data,id:crypto.randomUUID(),status:'Planejado'});save();document.querySelector('#taskDialog').close();refreshTaskViews();toast('Entrega salva.')};render();

function annotateCopy(){
 const nodes=[...document.querySelectorAll('#app h1,#app h2,#app h3,#app h4,#app p,#app .eyebrow,#app .checklist label span')].filter(el=>!el.closest('[data-text],#dailyProgram,#rosterTables,#scaleBoards,#scheduleTables,#board,#demandStats')&&!el.querySelector('button,input,select,a'));
 nodes.forEach((el,i)=>{const key='copy-'+i;el.dataset.copy=key;if(state.copy[key]!==undefined)el.textContent=state.copy[key]});
}
let scaleEditId=null;
function openScale(id){
 scaleEditId=id||null;const row=state.roster.find(r=>r.id===id);const form=document.querySelector('#scaleForm');form.reset();form.elements.day.value=row?.day||'1';form.elements.shift.value=row?.shift||'Manhã';
 document.querySelector('#scaleMemberFields').innerHTML=SCALE_ROLES.map((role,i)=>`<label>${esc(role)}<textarea name="member${i}" rows="2" placeholder="Nomes separados por vírgula">${esc(row?scaleMembers(row,i):'')}</textarea></label>`).join('');
 document.querySelector('#deleteScale').hidden=!id;document.querySelector('#scaleDialog').showModal();
}
document.querySelector('#cancelScale').onclick=()=>document.querySelector('#scaleDialog').close();
document.querySelector('#scaleForm').onsubmit=e=>{e.preventDefault();const form=e.target,d=form.elements.day.value,s=form.elements.shift.value;if(state.roster.some(r=>r.id!==scaleEditId&&r.day===d&&r.shift===s)){toast('Este dia e turno já existe. Edite o turno existente.');return}
 let row=state.roster.find(r=>r.id===scaleEditId);if(!row){row={id:crypto.randomUUID(),day:d,shift:s,members:SCALE_ROLES.map(()=>[])};state.roster.push(row)}row.day=d;row.shift=s;SCALE_ROLES.forEach((_,i)=>{const names=form.elements['member'+i].value.trim();state.scaleOwners[scaleKey(row,i)]=names;row.members[i]=names.split(/[,\n]/).map(x=>x.trim()).filter(Boolean)});save();document.querySelector('#scaleDialog').close();render();toast('Escala salva.');};
document.querySelector('#deleteScale').onclick=()=>{if(!confirm('Remover este turno da escala? As demandas da programação serão mantidas.'))return;state.roster=state.roster.filter(r=>r.id!==scaleEditId);save();document.querySelector('#scaleDialog').close();render();toast('Turno removido.');};

window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const data=JSON.parse(e.newValue);if(data.processText)state.processText=data.processText}catch{}}});

function arrivalWindow(time){const m=/^(\d{2}):(\d{2})$/.exec(time.trim());if(!m||+m[1]>23||+m[2]>59)return 'A confirmar';const n=+m[1]*60+ +m[2];const fmt=v=>{v=(v+1440)%1440;return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')};return fmt(n-60)+'–'+fmt(n-40)}
function renderSchedule(){return ['1','2','3','4','5'].filter(day=>state.schedule.some(r=>r.day===day)).map(day=>{const rows=state.schedule.filter(r=>r.day===day);return `<article class="roster-day" id="cronograma-dia-${day}"><div class="roster-title"><h3>${['','Sexta-feira','Sábado','Domingo','Segunda-feira','Terça-feira'][day]}</h3></div>${[...new Set(rows.map(r=>r.block))].map(block=>{const items=rows.filter(r=>r.block===block);return `<div class="schedule-block"><h4>${esc(block)}</h4><p class="arrival-window">Chegada para o início deste bloco: <strong>${esc(arrivalWindow(items[0].time))}</strong></p><div class="roster-table-wrap"><table class="schedule-table"><caption>${esc(block)}</caption><thead><tr><th>Horário</th><th>Momento</th><th>Ministro / condução</th>${editing?'<th>Edição</th>':''}</tr></thead><tbody>${items.map(r=>`<tr><td data-label="Horário"><strong data-schedule="${esc(r.id)}" data-field="time">${esc(r.time)}</strong></td><td data-label="Momento"><span data-schedule="${esc(r.id)}" data-field="title">${esc(r.title)}</span></td><td data-label="Ministro / condução"><span data-schedule="${esc(r.id)}" data-field="minister">${esc(r.minister)}</span></td>${editing?`<td><button data-edit-schedule="${esc(r.id)}">Editar momento</button></td>`:''}</tr>`).join('')}</tbody></table></div></div>`}).join('')}</article>`}).join('')}
let scheduleEditId=null;
function openSchedule(id){scheduleEditId=id||null;const row=state.schedule.find(r=>r.id===id);const form=document.querySelector('#scheduleForm');form.reset();['day','block','time','title','minister'].forEach(k=>form.elements[k].value=row?.[k]||(k==='day'?'1':''));document.querySelector('#deleteSchedule').hidden=!id;document.querySelector('#scheduleDialog').showModal()}
document.querySelector('#cancelSchedule').onclick=()=>document.querySelector('#scheduleDialog').close();
document.querySelector('#scheduleForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const old=state.schedule.find(r=>r.id===scheduleEditId);if(old)Object.assign(old,data);else state.schedule.push({...data,id:crypto.randomUUID()});save();document.querySelector('#scheduleDialog').close();render();toast('Cronograma salvo.')};
document.querySelector('#deleteSchedule').onclick=()=>{if(!confirm('Remover este momento do cronograma?'))return;state.schedule=state.schedule.filter(r=>r.id!==scheduleEditId);save();document.querySelector('#scheduleDialog').close();render()};

